<?php
 namespace Pterodactyl\Services\Dezerx; use Throwable; use Pterodactyl\Models\Server; use Pterodactyl\Models\EggVariable; use Pterodactyl\Models\ServerVariable; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Validator; class ServerVariables { public static function definition(Server $server, string $key): ?EggVariable { foreach ($server->variables as $variable) { if ($variable->env_variable === $key) { return $variable; } } return null; } public static function firstDefinition(Server $server, array $keys): ?EggVariable { foreach ($keys as $key) { $variable = self::definition($server, (string) $key); if ($variable !== null) { return $variable; } } return null; } public static function value(Server $server, string $key): ?string { $variable = self::definition($server, $key); return $variable === null ? null : self::valueOf($variable); } public static function valueOf(EggVariable $variable): string { $value = $variable->server_value; return $value === null || $value === '' ? (string) $variable->default_value : (string) $value; } public static function set(Server $server, string $key, string $value): bool { $variable = self::definition($server, $key); if ($variable === null) { return false; } $rules = (string) $variable->rules; if ($rules !== '' && Validator::make(['value' => $value], ['value' => $rules])->fails()) { return false; } try { ServerVariable::query()->updateOrCreate( ['server_id' => $server->id, 'variable_id' => $variable->id], ['variable_value' => $value], ); } catch (Throwable $exception) { Log::warning('Could not write a server variable', [ 'server' => $server->uuid, 'variable' => $key, 'error' => $exception->getMessage(), ]); return false; } $server->load('variables'); return true; } } 